end, {
	name = "Русский",
	listed = true,
	plural = function(n)
		if n ~= math.floor(n) then
			return "other"
		end
		local ten, hundred = n % 10, n % 100
		if ten == 1 and hundred ~= 11 then
			return "one"
		end
		if ten >= 2 and ten <= 4 and (hundred < 12 or hundred > 14) then
			return "few"
		end
		return "many"
	end,
	decimal = ",",
	thousands = " ",
})
